<?php
function customer_chat_admin():void{
 if(!chat_staff(admin()))abort(403,'Chat access is not enabled for your staff account.');$selected=(int)($_GET['conversation']??0);
 admin_page('Customer chat',function()use($selected){?><link rel="stylesheet" href="/public/assets/chat-660.css?v=6.6.0"><?php if(admin()['role']==='admin'):?><form class="form chat-owner-controls" method="post" action="/admin/chat/settings"><?=token()?><h3>Chat availability</h3><p class="muted">Pause new messages, reactions and typing updates for everyone. History remains available. Grant managers “Use customer chat” in Staff access.</p><input type="hidden" name="enabled" value="<?=chat_enabled()?'0':'1'?>"><button class="btn gold"><?=chat_enabled()?'Pause customer chat':'Enable customer chat'?></button><span class="status-pill"><?=chat_enabled()?'Active':'Paused'?></span></form><?php endif;?>
 <div class="team-chat-layout"><aside class="form team-chat-threads"><h3>Conversations</h3><div data-team-threads data-csrf="<?=esc(csrf())?>"><?php foreach(all('SELECT c.id,u.name,(SELECT COUNT(*) FROM chat_messages m WHERE m.conversation_id=c.id AND m.sender_role=\'customer\' AND m.id>c.staff_read_id) unread FROM chat_conversations c JOIN users u ON u.id=c.user_id ORDER BY c.updated_at DESC LIMIT 80') as $thread):?><a href="/admin/chat?conversation=<?=$thread['id']?>"><strong><?=esc($thread['name'])?></strong><small><?=(int)$thread['unread']?> unread</small></a><?php endforeach;?></div></aside><div><?php if($selected&&one('SELECT id FROM chat_conversations WHERE id=?',[$selected])):chat_markup(true,$selected);else:?><section class="form"><h2>A seat at the conversation.</h2><p class="muted">Select a customer conversation to reply. This inbox updates while open.</p></section><?php endif;?></div></div><script src="/public/assets/chat-660.js?v=6.6.0" defer></script><script src="/public/assets/team-chat-660.js?v=6.6.0" defer></script><?php });
}
function customer_requests_admin():void{
 if(admin()['role']!=='admin')abort(403,'Owner access required');admin_page('Returns & customer requests',function(){?><p class="muted">Replies and statuses appear in the customer's dashboard. A request does not move money. For an approved refund, review the successful payment under Refund reviews; wallet payments return to the same wallet.</p><?php foreach(all('SELECT r.*,u.name FROM customer_requests r JOIN users u ON u.id=r.user_id ORDER BY r.id DESC LIMIT 100') as $request):?><section class="admin-panel"><h3>#<?=$request['id']?> · <?=esc($request['subject'])?></h3><p><?=esc($request['name'])?> · <?=esc($request['kind'])?><?php if($request['order_id']):?> · <a href="/order/<?=$request['order_id']?>">Order #<?=$request['order_id']?></a><?php endif;?></p><p><?=nl2br(esc($request['message']))?></p><form method="post" action="/admin/customer-request/reply"><?=token()?><input name="id" type="hidden" value="<?=$request['id']?>"><label>Status<select name="status"><?php foreach(['open','reviewing','resolved','rejected'] as $status):?><option <?=$request['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></label><label>Reply<textarea name="reply" maxlength="3000" rows="3"><?=esc($request['reply']??'')?></textarea></label><button class="btn gold">Save reply</button></form></section><?php endforeach;?><?php });
}

function customer_wallet_admin():void{
 if(admin()['role']!=='admin')abort(403,'Owner access required');admin_page('Customer wallets',function(){
 ?><?php $diagnostic=json_decode(mail_setting('wallet_last_verification_error','{}'),true);$worker=json_decode(mail_setting('wallet_worker_last_result','{}'),true);?><section class="admin-panel"><h2>Automatic verification</h2><p class="muted">Paystack callbacks and signed webhooks verify top-ups automatically. The existing mail cron also retries pending top-ups without creating another charge. Customers can use Check status to recover a payment immediately.</p><?php if(!empty($worker['time'])):?><p>Last background check: <?=esc(date('d M Y H:i:s',(int)$worker['time']))?> · <?=(int)($worker['result']['checked']??0)?> checked · <?=(int)($worker['result']['credited']??0)?> credited.</p><?php else:?><p>Keep your existing cPanel mail cron running to enable background recovery.</p><?php endif;if(!empty($diagnostic['time'])):?><details><summary>Latest verification diagnostic</summary><p><?=esc($diagnostic['reference']??'')?> · <?=esc($diagnostic['stage']??'')?> · <?=esc($diagnostic['type']??'')?> · <?=esc($diagnostic['sqlstate']??'')?> / <?=(int)($diagnostic['driver_code']??0)?> · <?=esc(date('d M Y H:i:s',(int)$diagnostic['time']))?></p><p class="muted">This is a historical error record. Check the top-up status below; a receipt error does not reverse credited funds. Share this code when requesting support.</p></details><?php endif;?></section><p class="muted">Balances are backed by the wallet ledger. Test and live funds are separate. Only verified top-ups and approved wallet refunds credit an account; there is no arbitrary balance-edit form.</p><div class="scroll"><table><tr><th>Account</th><th>Environment</th><th>Balance</th><th>Ledger total</th></tr><?php foreach(all('SELECT a.*,u.name,u.email,(SELECT COALESCE(SUM(l.amount),0) FROM wallet_ledger l WHERE l.user_id=a.user_id AND l.mode=a.mode) ledger_total FROM wallet_accounts a JOIN users u ON u.id=a.user_id ORDER BY a.user_id DESC LIMIT 100') as $account):?><tr><td><?=esc($account['name'])?><small><?=esc($account['email'])?></small></td><td><?=esc($account['mode'])?></td><td><?=money((int)$account['balance']/100)?></td><td><?=money((int)$account['ledger_total']/100)?><?php if((int)$account['balance']!==(int)$account['ledger_total']):?> · Review required<?php endif;?></td></tr><?php endforeach;?></table></div><h2>Recent top-ups</h2><div class="scroll"><table><tr><th>Reference</th><th>Account</th><th>Amount</th><th>Environment</th><th>Status</th><th>Action</th></tr><?php foreach(all('SELECT t.id,t.reference,t.user_id,t.amount,t.mode,t.status,u.email FROM wallet_topups t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 100') as $topup):?><tr><td><?=esc($topup['reference'])?></td><td><?=esc($topup['email'])?></td><td><?=money((int)$topup['amount']/100)?></td><td><?=esc($topup['mode'])?></td><td><?=esc($topup['status'])?></td><td><?php if($topup['status']!=='success'):?><form method="post" action="/admin/wallet/verify"><?=token()?><input name="reference" type="hidden" value="<?=esc($topup['reference'])?>"><button class="btn">Verify with provider</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php });
}
